#include <bits/stdc++.h>
using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int H, W;
    cin >> H >> W;

    vector<vector<int>> a(H, vector<int>(W));
    for (int i = 0; i < H; i++)
        for (int j = 0; j < W; j++)
            cin >> a[i][j];

    // dp[r1][r2] = max souvenirs when both are at step t
    // r1 is row of person1, r2 is row of person2
    // col1 = t - r1, col2 = t - r2

    int steps = H + W - 2;

    // Use -infinity for invalid states
    const int NEG_INF = -1e9;

    vector<vector<int>> dp(H, vector<int>(H, NEG_INF));
    dp[0][0] = a[0][0];

    for (int t = 1; t <= steps; t++) {
        vector<vector<int>> ndp(H, vector<int>(H, NEG_INF));

        for (int r1 = 0; r1 < H; r1++) {
            int c1 = t - r1;
            if (c1 < 0 || c1 >= W) continue;

            for (int r2 = 0; r2 < H; r2++) {
                int c2 = t - r2;
                if (c2 < 0 || c2 >= W) continue;

                // Try all previous states (r1 came from r1 or r1-1, r2 came from r2 or r2-1)
                int best = NEG_INF;

                // prev_r1 can be r1 (moved right) or r1-1 (moved down)
                // prev_r2 can be r2 (moved right) or r2-1 (moved down)
                for (int pr1 : {r1, r1 - 1}) {
                    if (pr1 < 0) continue;
                    int pc1 = (t-1) - pr1;
                    if (pc1 < 0 || pc1 >= W) continue;

                    for (int pr2 : {r2, r2 - 1}) {
                        if (pr2 < 0) continue;
                        int pc2 = (t-1) - pr2;
                        if (pc2 < 0 || pc2 >= W) continue;

                        if (dp[pr1][pr2] != NEG_INF) {
                            best = max(best, dp[pr1][pr2]);
                        }
                    }
                }

                if (best == NEG_INF) continue;

                int gain;
                if (r1 == r2) {
                    // Same cell
                    gain = a[r1][c1];
                } else {
                    gain = a[r1][c1] + a[r2][c2];
                }

                ndp[r1][r2] = max(ndp[r1][r2], best + gain);
            }
        }

        dp = ndp;
    }

    cout << dp[H-1][H-1] << endl;

    return 0;
}

