    vector<vector<long long>> dp(H, vector<long long>(W, LLONG_MIN));
    dp[0][0] = a[0][0];

    for (int i = 0; i < H; ++i) {
        for (int j = 0; j < W; ++j) {
            if (i > 0) dp[i][j] = max(dp[i][j], dp[i - 1][j] + a[i][j]);
            if (j > 0) dp[i][j] = max(dp[i][j], dp[i][j - 1] + a[i][j]);
        }
    }

    cout << dp[H - 1][W - 1] << '\n';
    return 0;
}

#include <stdio.h>

int main() {
    int H, W;
    scanf("%d %d", &H, &W);

    int grid[H][W];
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            scanf("%d", &grid[i][j]);
        }
    }

    // DP table
    int dp[H][W];
    dp[0][0] = grid[0][0];

    // Initialize first row
    for (int j = 1; j < W; j++) {
        dp[0][j] = dp[0][j-1] + grid[0][j];
    }

    // Initialize first column
    for (int i = 1; i < H; i++) {
        dp[i][0] = dp[i-1][0] + grid[i][0];
    }

    // Fill rest
    for (int i = 1; i < H; i++) {
        for (int j = 1; j < W; j++) {
            if (dp[i-1][j] > dp[i][j-1]) {
                dp[i][j] = dp[i-1][j] + grid[i][j];
            } else {
                dp[i][j] = dp[i][j-1] + grid[i][j];
            }
        }
    }

    printf("%d\n", dp[H-1][W-1]);

    return 0;
}

#include <stdio.h>
