#define MAXN 55
#define NEG_INF -1000000000

int a[MAXN][MAXN];
int dp[2][MAXN][MAXN];
int H, W;

int max(int x, int y) { return x > y ? x : y; }

int main() {
    scanf("%d %d", &H, &W);
    for (int i = 0; i < H; i++)
        for (int j = 0; j < W; j++)
            scanf("%d", &a[i][j]);

    // dp[r1][r2] = max souvenirs after t steps
    // Initialize
    for (int r1 = 0; r1 < H; r1++)
        for (int r2 = 0; r2 < H; r2++)
            dp[0][r1][r2] = NEG_INF;

    // t=0: both at (0,0)
    dp[0][0][0] = a[0][0];

    int cur = 0, nxt = 1;

    for (int t = 0; t < H + W - 2; t++) {
        for (int r1 = 0; r1 < H; r1++)
            for (int r2 = 0; r2 < H; r2++)
                dp[nxt][r1][r2] = NEG_INF;

        for (int r1 = 0; r1 < H; r1++) {
            int c1 = t - r1;
            if (c1 < 0 || c1 >= W) continue;
            for (int r2 = 0; r2 < H; r2++) {
                int c2 = t - r2;
                if (c2 < 0 || c2 >= W) continue;
                if (dp[cur][r1][r2] == NEG_INF) continue;

                // Try all 4 move combinations
                int dr[] = {0, 1};
                int dc[] = {1, 0};
                for (int m1 = 0; m1 < 2; m1++) {
                    int nr1 = r1 + dr[m1];
                    int nc1 = c1 + dc[m1];
                    if (nr1 >= H || nc1 >= W) continue;
                    for (int m2 = 0; m2 < 2; m2++) {
                        int nr2 = r2 + dr[m2];
                        int nc2 = c2 + dc[m2];
                        if (nr2 >= H || nc2 >= W) continue;

                        int val = dp[cur][r1][r2];
                        if (nr1 == nr2 && nc1 == nc2)
                            val += a[nr1][nc1];
                        else
                            val += a[nr1][nc1] + a[nr2][nc2];

                        if (val > dp[nxt][nr1][nr2])
                            dp[nxt][nr1][nr2] = val;
                    }
                }
            }
        }
        cur = nxt; nxt = 1 - cur;
    }

    printf("%d\n", dp[cur][H-1][H-1]);
    return 0;
}

#include <stdio.h>
