static long long maxll(long long a, long long b) {
    return a > b ? a : b;
}

int main(void) {
    int H, W;
    if (scanf("%d %d", &H, &W) != 2) return 0;

    long long **a = (long long **)malloc(H * sizeof(long long *));
    for (int i = 0; i < H; i++) {
        a[i] = (long long *)malloc(W * sizeof(long long));
        for (int j = 0; j < W; j++) {
            scanf("%lld", &a[i][j]);
        }
    }

    /*
      Since they must reach (H-1, W-1) in exactly H+W-2 moves,
      they cannot waste moves. Therefore every move must be either
      right or down, and the problem becomes the classic maximum-sum path.

      dp[i][j] = maximum souvenirs collectible upon reaching cell (i, j)
    */
    long long **dp = (long long **)malloc(H * sizeof(long long *));
    for (int i = 0; i < H; i++) {
        dp[i] = (long long *)malloc(W * sizeof(long long));
    }

    dp[0][0] = a[0][0];

    for (int i = 1; i < H; i++) {
        dp[i][0] = dp[i - 1][0] + a[i][0];
    }
    for (int j = 1; j < W; j++) {
        dp[0][j] = dp[0][j - 1] + a[0][j];
    }

    for (int i = 1; i < H; i++) {
        for (int j = 1; j < W; j++) {
            dp[i][j] = maxll(dp[i - 1][j], dp[i][j - 1]) + a[i][j];
        }
    }

    printf("%lld\n", dp[H - 1][W - 1]);

    for (int i = 0; i < H; i++) {
        free(a[i]);
        free(dp[i]);
    }
    free(a);
    free(dp);

    return 0;
}

