import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int H = fs.nextInt();
        int W = fs.nextInt();

        long[][] a = new long[H][W];
        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                a[i][j] = fs.nextLong();
            }
        }

        // Since they must reach from (0,0) to (H-1,W-1) in exactly H+W-2 moves,
        // every move must be either right or down.
        // So the problem is the maximum-sum path in a grid.
        long[][] dp = new long[H][W];

        dp[0][0] = a[0][0];

        for (int i = 1; i < H; i++) {
            dp[i][0] = dp[i - 1][0] + a[i][0];
        }
        for (int j = 1; j < W; j++) {
            dp[0][j] = dp[0][j - 1] + a[0][j];
        }

        for (int i = 1; i < H; i++) {
            for (int j = 1; j < W; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + a[i][j];
            }
        }

        System.out.println(dp[H - 1][W - 1]);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }
}

